// Descarta promociones, redes sociales y spam.
const labels = $json.labelIds || [];
const ruido = ['CATEGORY_PROMOTIONS', 'CATEGORY_SOCIAL', 'CATEGORY_FORUMS', 'SPAM', 'TRASH'];
if (labels.some((l) => ruido.includes(l))) {
  return null; // el item se descarta
}
return { json: {
  id: $json.id,
  threadId: $json.threadId,
  subject: $json.subject || '(sin asunto)',
  from: $json.from || '',
  date: $json.date || '',
  text: ($json.text || $json.snippet || '').slice(0, 3000),
} };

const store = $getWorkflowStaticData('global');
const seen = store.emailSeen || {};
const now = Date.now();
const TTL = 14 * 24 * 60 * 60 * 1000;
for (const k of Object.keys(seen)) { if (now - seen[k] > TTL) delete seen[k]; }
const out = [];
for (const item of $input.all()) {
  const key = item.json.id;
  if (!key || seen[key]) continue;
  seen[key] = now;
  out.push({ json: item.json, pairedItem: item.pairedItem });
}
store.emailSeen = seen;
return out;

