let a;
try {
  const raw = ($json.candidates && $json.candidates[0] && $json.candidates[0].content
    && $json.candidates[0].content.parts && $json.candidates[0].content.parts[0]
    && $json.candidates[0].content.parts[0].text) || '{}';
  a = JSON.parse(raw);
} catch (e) {
  throw new Error('Análisis de Gemini no es JSON válido: ' + e.message);
}

let email = {};
try { email = $('Deduplicar correos').item.json; } catch (e) {}
const ev = a.evento || {};
const crearEvento = ev.crear === true && !!ev.inicio;

return { json: {
  subject: email.subject || '',
  from: email.from || '',
  categoria: a.categoria || 'otro',
  prioridad: a.prioridad || 'media',
  requiere_accion: a.requiere_accion === true,
  resumen: a.resumen || '',
  crearEvento,
  evento_titulo: ev.titulo || email.subject || 'Cita',
  evento_inicio: ev.inicio || '',
  evento_fin: ev.fin || ev.inicio || '',
  evento_descripcion: ev.descripcion || ''
} };
